package com.opensocket.aievent.core.resourceaccess.persistence;
import com.opensocket.aievent.core.resourceaccess.contract.*;import com.opensocket.aievent.database.persistence.spi.DatabaseRepositoryAdapter;import java.sql.Timestamp;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;
@DatabaseRepositoryAdapter @ConditionalOnProperty(prefix="resource-access",name={"enabled","background-enabled"},havingValue="true")
public final class JdbcBackgroundAuthorizationAuditAdapter implements BackgroundAuthorizationAuditPort {private final JdbcTemplate jdbc;public JdbcBackgroundAuthorizationAuditAdapter(JdbcTemplate j){jdbc=Objects.requireNonNull(j);}@Override public void append(BackgroundJobAuthorization a,String purpose,String correlation){if(a.resourceRefs().isEmpty())return;String tenant=a.resourceRefs().getFirst().tenantId();jdbc.update("insert into resource_background_authorization_audits(tenant_id,audit_id,authorization_id,job_code,principal_id,decision_ids_text,resource_refs_text,runtime_lease_ids_text,executable,purpose,correlation_id,evaluated_at,created_at) values(?,?,?,?,?,?,?,?,?,?,?,?,?)",tenant,"baa-"+UUID.randomUUID(),a.authorizationId(),a.jobCode(),a.principalId(),String.join("\n",a.decisionIds()),a.resourceRefs().stream().map(r->r.resourceType()+":"+r.resourceId()).collect(java.util.stream.Collectors.joining("\n")),a.runtimeLeases().stream().map(RuntimeAuthorizationLease::leaseId).collect(java.util.stream.Collectors.joining("\n")),a.executable(),purpose,correlation,Timestamp.from(a.evaluatedAt()),Timestamp.from(a.evaluatedAt()));}}
